import{c as s,$ as n,Q as l,j as g,g as o,o as i,n as e,m as a}from"./chunks/framework.Ce_49mA8.js";const q=JSON.parse('{"title":"Онлайн-витрина и интернет-магазин","description":"Встроенный генератор автономной витрины (на основе статической генерации), дизайн «Деликатный премиум», суверенный чекаут с E2EE-защитой, мультивитрины и единый стол заказов в ОмниКрафт ЕРП.","frontmatter":{"title":"Онлайн-витрина и интернет-магазин","description":"Встроенный генератор автономной витрины (на основе статической генерации), дизайн «Деликатный премиум», суверенный чекаут с E2EE-защитой, мультивитрины и единый стол заказов в ОмниКрафт ЕРП.","datePublished":"2026-08-20","dateModified":"2026-11-28","order":6},"headers":[],"relativePath":"ru/docs/resources/web-store.md","filePath":"ru/docs/resources/web-store.md","lastUpdated":1795824000000}'),d={name:"ru/docs/resources/web-store.md"},c={id:"онлаин-витрина-и-интернет-магазин",tabindex:"-1"};function h(p,t,u,m,b,f){const r=n("DocIcon");return l(),g("div",null,[o("h1",c,[i(r,{name:"showcase"}),t[0]||(t[0]=e(" Онлайн-витрина и интернет-магазин ",-1)),t[1]||(t[1]=o("a",{class:"header-anchor",href:"#онлаин-витрина-и-интернет-магазин","aria-label":'Permalink to "Онлайн-витрина и интернет-магазин"'},"​",-1))]),t[2]||(t[2]=a('<p>Встроенный модуль <strong>«Витрина»</strong> превращает базу изделий, каталог услуг и складские остатки в автономный, быстрый и современный интернет-магазин. Вы получаете независимую публичную площадку без абонентской платы сторонним конструкторам сайтов и без уязвимых серверных систем управления контентом.</p><p>Витрина компилируется по технологии статической генерации (Джемстек): на выходе формируется чистый комплект автономных файлов — разметка HTML, таблицы стилей CSS, легковесные скрипты на чистом JavaScript и оптимизированная растровая графика.</p><p>Сайт открывается моментально на смартфонах и компьютерах, не требует базы данных на сервере и бесплатно размещается на надежных площадках: в объектных хранилищах S3, через прямое развертывание на платформе Клаудфлейр, на страницах ГитХаб или на традиционном хостинге по протоколу передачи файлов FTP.</p><hr><h2 id="архитектура-независимости-преимущества-сувереннои-витрины" tabindex="-1">Архитектура независимости: Преимущества суверенной витрины <a class="header-anchor" href="#архитектура-независимости-преимущества-сувереннои-витрины" aria-label="Permalink to &quot;Архитектура независимости: Преимущества суверенной витрины&quot;">​</a></h2><p>Витрина создана специально для прикладных мастеров, сервисных специалистов и локальных производств. Система устраняет посредников между создателем и заказчиком.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Подсистема витрины</th><th style="text-align:left;">Назначение в ОмниКрафт ЕРП</th><th style="text-align:left;">Практическая выгода для дела</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Дизайн «Деликатный премиум»</strong></td><td style="text-align:left;">Автономная типографика Inter WOFF2, латунные акценты, светлая и тёмная темы оформления</td><td style="text-align:left;">Высокая эстетика ручного труда без зависимости от внешних шрифтовых серверов</td></tr><tr><td style="text-align:left;"><strong>Многостраничная структура</strong></td><td style="text-align:left;">Главная витрина, каталог с фильтрами, детальные карточки, разделы доставки и журнал</td><td style="text-align:left;">Полноценный сайт мастерской вместо примитивного одностраничного прайс-листа</td></tr><tr><td style="text-align:left;"><strong>Модульные карточки позиций</strong></td><td style="text-align:left;">Конструктор секций: вводный лид, сетка преимуществ, история, фотогалерея, видео, спецификация, ответы на частые вопросы</td><td style="text-align:left;">Убедительная демонстрация штучных изделий и сложных сервисных услуг</td></tr><tr><td style="text-align:left;"><strong>Суверенный чекаут и E2EE-защита</strong></td><td style="text-align:left;">Бессерверная корзина, прямое шифрование по алгоритмам RSA-2048 и AES-256-GCM, бот Телеграм и серверная форма</td><td style="text-align:left;">Полная автономия: персональные данные покупателей доступны исключительно мастеру</td></tr><tr><td style="text-align:left;"><strong>Встроенный предпросмотр</strong></td><td style="text-align:left;">Локальный многопоточный сервер с жестким запретом кэширования для оперативной проверки</td><td style="text-align:left;">Моментальная оценка витрины в браузере до выгрузки на рабочий хостинг</td></tr><tr><td style="text-align:left;"><strong>Гибкая выгрузка сайта</strong></td><td style="text-align:left;">Прямая публикация на Клаудфлейр, хранилище S3, протокол FTP/SFTP, локальный архив</td><td style="text-align:left;">Бесплатное или предельно дешевое размещение и моментальное обновление по контрольным суммам</td></tr><tr><td style="text-align:left;"><strong>Единый стол заказов</strong></td><td style="text-align:left;">Централизованный прием заявок, умная вставка из буфера, быстрые ответы и списание остатков по ФИФО</td><td style="text-align:left;">Исключение ошибок ручной записи и учет реального складского наличия</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Автономия от чужих серверов и комиссий</p><p>В отличие от облачных конструкторов сайтов, витрина <strong>ОмниКрафт ЕРП</strong> не заблокируется из-за санкций, не списывает комиссию с каждой продажи и не показывает клиентам чужую рекламу. Вся клиентская база и исходный код принадлежат только вам.</p></div><hr><h2 id="устроиство-и-возможности-витрины" tabindex="-1">Устройство и возможности витрины <a class="header-anchor" href="#устроиство-и-возможности-витрины" aria-label="Permalink to &quot;Устройство и возможности витрины&quot;">​</a></h2><h3 id="_1-универсальная-модульная-главная-страница" tabindex="-1">1. Универсальная модульная главная страница <a class="header-anchor" href="#_1-универсальная-модульная-главная-страница" aria-label="Permalink to &quot;1. Универсальная модульная главная страница&quot;">​</a></h3><p>Главная страница спроектирована под разные форматы деятельности — авторские ремесленные мастерские, сервисные центры по ремонту оборудования или комбинированные студии. Каждый визуальный блок настраивается независимо:</p><ul><li><strong>Верхняя информационная лента:</strong> опциональная полоса над шапкой для уведомлений об акциях, графике работы или сроках изготовления. Посетитель может закрыть ленту, и выбор сохранится в его текущей сессии.</li><li><strong>Три композиции первого экрана:</strong><ul><li><em>«Триптих»</em> — монументальный сбалансированный макет с тремя визуальными колонками;</li><li><em>«Разделённый экран»</em> — современная композиция с пропорцией 50 на 50;</li><li><em>«Широкий баннер»</em> — кинематографичный полноэкранный блок с контрастным затемнением.</li></ul></li><li><strong>Ручной слайдер баннеров:</strong> поддержка от одного до трех слайдов с ручным переключением (стрелки, точки, смахивание на экранах смартфонов). Навязчивая автоматическая прокрутка исключена, чтобы покупатель мог спокойно рассмотреть изделия. Если баннеры не загружены, система автоматически выводит первое опубликованное изделие.</li><li><strong>Кнопка вопроса с баннера:</strong> при подключении Телеграм или WhatsApp на широком баннере появляется кнопка «Задать вопрос», открывающая прямое окно диалога с мастером.</li><li><strong>Двенадцать отключаемых секций главной страницы:</strong> строка доверия с векторными пиктограммами, витрина категорий с портретными карточками пропорции 3:4, блоки новинок и популярных позиций, компактная прайс-лента с переключением вкладок, сквозной промо-баннер, этапы работы, авторский блок «Слово мастера» (с портретом, фактами и личной подписью), статьи журнала, отзывы клиентов, раскрывающиеся ответы на частые вопросы и финальный блок связи.</li><li><strong>Полноэкранное навигационное меню:</strong> кнопка меню разворачивает матовый оверлей на весь экран. Структура разделена на два потока: левая колонка отведена под направления каталога, правая — под страницы условий доставки, оплаты, историю мастерской и контакты.</li><li><strong>Интеллектуальная кнопка навигации:</strong> компактный кружок прокрутки на первом экране скрыт, чтобы не отвлекать внимание. При прокрутке вниз стрелка указывает в подвал к контактам мастерской, а в нижней части страницы разворачивается вверх для мгновенного возврата к каталогу.</li></ul><hr><h3 id="_2-карточка-изделия-и-услуги" tabindex="-1">2. Карточка изделия и услуги <a class="header-anchor" href="#_2-карточка-изделия-и-услуги" aria-label="Permalink to &quot;2. Карточка изделия и услуги&quot;">​</a></h3><p>Страница позиции воплощает культуру уважения к качеству и труду создателя:</p><ul><li><strong>Пространственная галерея триптих:</strong> полноэкранный кинематографичный слайдер первого экрана с эффектом трехмерной глубины. Активная центральная фотография сопровождается боковыми ракурсами под углом, создавая объемное восприятие предмета.</li><li><strong>Парящий блок первого знакомства:</strong> аккуратная панель поверх нижнего края галереи с крупным названием, ценой, якорной кнопкой «ПОДРОБНЕЕ» и кнопкой переключения модификаций («ДРУГИЕ ЦВЕТА», «ВАРИАНТЫ МАТЕРИАЛА»).</li><li><strong>Двухколоночный детальный блок:</strong><ul><li><em>Левая плавающая панель покупки:</em> фиксируется при прокрутке экрана. Держит перед глазами покупателя крупную цену, префикс «от », выбор модификаций, монументальную кнопку добавления в корзину, кнопки мгновенной связи в мессенджерах и условия бережной доставки.</li><li><em>Правая колонка содержательного рассказа:</em> повествование мастера с классической буквицей, маркированный список технологических достоинств, личная авторская цитата и стек модульных блоков описания.</li></ul></li><li><strong>Модульный конструктор описания позиции:</strong><ul><li><em>Вводный лид:</em> эмоциональное и емкое описание назначения предмета крупным кеглем;</li><li><em>Сетка преимуществ:</em> карточки с пиктограммами, раскрывающие инженерные особенности;</li><li><em>История создания:</em> рассказ о подборе сырья, ручной формовке или авторской сборке;</li><li><em>Дополнительная галерея (лукбук):</em> подборка атмосферных фотографий в интерьере или рабочем процессе;</li><li><em>Видеодемонстрация:</em> адаптер с облегченным фасадом для роликов из ВКонтакте, Рутуба или Ютуба (внешние скрипты не загружаются до первого нажатия, обеспечивая чистоту трафика);</li><li><em>Спецификация:</em> таблица физических параметров (размеры, материал, фурнитура, масса);</li><li><em>Частые вопросы по позиции:</em> раскрывающийся аккордеон с рекомендациями по эксплуатации и уходу.</li></ul></li></ul><hr><h3 id="_3-суверенныи-чекаут-и-сквозная-защита-данных" tabindex="-1">3. Суверенный чекаут и сквозная защита данных <a class="header-anchor" href="#_3-суверенныи-чекаут-и-сквозная-защита-данных" aria-label="Permalink to &quot;3. Суверенный чекаут и сквозная защита данных&quot;">​</a></h3><p>Программа реализует безопасный контур оформления заказов без передачи конфиденциальной информации посредникам:</p><ol><li><strong>Три режима оформления на выбор покупателя:</strong><ul><li><em>Прямой диалог в Телеграм:</em> переход в личный чат или канал с сформированной карточкой выбранных позиций;</li><li><em>Прямой диалог в WhatsApp:</em> мгновенный запуск чата с предзаполненным списком изделий, опций и расчетом стоимости;</li><li><em>Бессерверная корзина сайта:</em> классическое оформление заказа непосредственно на страницах витрины.</li></ul></li><li><strong>Сквозное шифрование данных покупателя:</strong><ul><li>Контактные данные заказчика (имя, номер телефона, адрес доставки, примечание) шифруются непосредственно в браузере покупателя симметричным шифром AES-256-GCM.</li><li>Сессионный ключ упаковывается асимметричным алгоритмом RSA-OAEP с длиной ключа 2048 бит с использованием открытого ключа витрины, сгенерированного программой.</li><li>Закрытый ключ хранится исключительно в локальной базе данных <strong>ОмниКрафт ЕРП</strong> на вашем компьютере под защитой системного хранилища операционной системы Windows DPAPI.</li><li>Ни хостинг сайта, ни сторонние наблюдатели не имеют технической возможности прочитать зашифрованные данные покупателя без закрытого ключа в вашей программе.</li></ul></li><li><strong>Два транспортных шлюза передачи заявок:</strong><ul><li><em>Официальный бот Телеграм:</em> прямая защищенная отправка шифропакета из браузера в ваш рабочий чат без промежуточных серверов;</li><li><em>Серверная форма:</em> отправка заказа через обработчик на хостинге, который поддерживает PHP.</li></ul></li><li><strong>Правовой контур:</strong><ul><li>Генератор автоматически создает страницы «Политика конфиденциальности» (<code>/pages/privacy</code>) и «Публичная оферта» (<code>/pages/terms</code>) с автоматической подстановкой ваших реквизитов (самозанятый, ИП, мастерская).</li><li>В форму чекаута встроен обязательный пункт подтверждения согласия на обработку персональных данных.</li></ul></li></ol><div class="warning custom-block"><p class="custom-block-title">Токен бота доступен посетителям при отправке из браузера</p><p>При выборе канала «Telegram-бот» токен бота и идентификатор чата входят в исходный код страниц витрины даже при шифровании заказов. Серверный обработчик и прямой диалог публикуют страницы без этих реквизитов. Если токен уже был доступен на опубликованных страницах, перевыпустите его, выберите другой канал приёма заказов и заново опубликуйте витрину.</p></div><p>Витрина подтверждает оформление, когда бот принял сообщение. Если отправку не удалось подтвердить, корзина и заполненные поля остаются на странице. Добавьте открытый контакт в Телеграме или WhatsApp, чтобы покупатель мог написать вам напрямую при сбое.</p><hr><h2 id="пошаговое-руководство-от-настроики-до-первои-публикации" tabindex="-1">Пошаговое руководство: От настройки до первой публикации <a class="header-anchor" href="#пошаговое-руководство-от-настроики-до-первои-публикации" aria-label="Permalink to &quot;Пошаговое руководство: От настройки до первой публикации&quot;">​</a></h2><h3 id="шаг-1-настроика-параметров-в-панели-«управление-саитом»" tabindex="-1">Шаг 1. Настройка параметров в панели «Управление сайтом» <a class="header-anchor" href="#шаг-1-настроика-параметров-в-панели-«управление-саитом»" aria-label="Permalink to &quot;Шаг 1. Настройка параметров в панели «Управление сайтом»&quot;">​</a></h3><p>Откройте вкладку <strong>«Витрина»</strong> → подвкладку <strong>«Управление сайтом»</strong>. Боковое меню разделено на четыре логические группы:</p><ol><li><strong>Группа «1. ОСНОВА И ДИЗАЙН»:</strong><ul><li><strong>Бренд и контакты:</strong> заполните поле <strong>«Адрес сайта»</strong> над логотипом. Можно ввести домен или полный адрес с путём, например <code>https://shop.example.com/catalogue</code>. Этот адрес используется в предпросмотре ссылок, карте сайта и кнопке <strong>«Открыть сайт»</strong>. Загрузите векторный файл SVG или растровый логотип (WebP, PNG, JPG). Выберите цветовую палитру загруженного файла (светлый, тёмный или цветной), чтобы он автоматически оставался контрастным при переключении тем оформления витрины. Настройте цветовую тему по умолчанию (светлая, тёмная или системная) и выберите подложку под снимки позиций (студийный тон или режим «Без подложки»). Заполните телефон в международном виде (+7), город, электронную почту и ссылки на используемые мессенджеры и социальные сети. В блоке <strong>«Тема оформления витрины»</strong> по умолчанию включена <strong>«Подпись „Сделано с помощью ОмниКрафт ЕРП“»</strong>. Она ведёт на сайт программы. На тарифе ПРО подпись можно отключить для выбранной витрины. Нажмите <strong>«Сохранить изменения»</strong> внизу раздела, затем <strong>«Опубликовать сайт»</strong>, чтобы обновить подпись на опубликованных страницах.</li><li><strong>Главная и Меню:</strong> выберите подходящий профиль быстрого старта («Ремесленная мастерская», «Услуги и сервис» или «Товары и услуги»). Настройте баннеры первого экрана и порядок секций главной. На вкладке <strong>«Навигационное меню»</strong> правая колонка объединяет отмеченные страницы и свои ссылки. Добавляйте ссылки кнопкой <strong>«Добавить пункт»</strong> и меняйте порядок командами <strong>«Выше»</strong> и <strong>«Ниже»</strong>.</li><li><strong>Главный баннер.</strong> Раскройте блок <strong>«Первый экран»</strong>, выберите макет, настройте тексты и кнопки. В широком баннере можно добавить до трёх слайдов. Если <a href="./../global-settings">внешний агент</a> изменил баннер после открытия редактора, скопируйте свой черновик, откройте настройки заново и внесите правки в свежую версию. При первом открытии блок свёрнут. Программа сразу запоминает его положение и восстанавливает после перезапуска.</li><li><strong>Промобаннер.</strong> На вкладке <strong>«Главная страница»</strong> раскройте <strong>«Промо-баннер в теле страницы»</strong>. Укажите текст предложения, добавьте изображение и задайте адрес кнопки. Включите показ блока и нажмите <strong>«Сохранить изменения»</strong>.</li><li><strong>Этапы работы.</strong> На вкладке <strong>«Главная страница»</strong> раскройте блок <strong>«Этапы работы («Как мы работаем»)»</strong>. Добавьте шаги в порядке, в котором покупатель выполнит их, и нажмите <strong>«Сохранить изменения»</strong>. Если <a href="./../global-settings">внешний агент</a> изменил этот же блок, скопируйте свои правки и откройте настройки заново перед сохранением.</li><li><strong>Объявление над страницей.</strong> В блоке <strong>«Верхняя строка»</strong> включите показ, введите текст объявления и при необходимости укажите подпись и адрес ссылки.</li><li><strong>Карточки преимуществ.</strong> В блоке <strong>«Полоса доверия и преимуществ (3–4 пункта)»</strong> задайте пиктограммы, заголовки и описания карточек. Первыми поставьте до четырёх карточек, которые увидят покупатели. Нажмите <strong>«Сохранить изменения»</strong>. Если удалить все карточки, полоса исчезнет при следующей сборке витрины.</li><li><strong>Сетка направлений.</strong> В редакторе каждой нужной категории отметьте <strong>«Показывать в сетке направлений»</strong>. На вкладке <strong>«Главная страница»</strong> откройте <strong>«Сетка направлений (Категории / Услуги)»</strong>, включите блок, задайте заголовок и подзаголовок и расставьте карточки. Нажмите <strong>«Сохранить изменения»</strong>. Если состав карточек изменился во время перестановки, откройте настройки заново и повторите её.</li><li><strong>Хиты продаж:</strong> на вкладке <strong>«Главная страница»</strong> раскройте блок <strong>«Выбор мастера / Хиты продаж»</strong>. Режим <strong>«Автоматически»</strong> подбирает товары по числу проданных единиц по всем каналам. В поле <strong>«Период продаж»</strong> по умолчанию стоят 90 дней. Можно выбрать другой период или задать даты через <strong>«Свой период»</strong>.</li><li><strong>Сохранение хитов.</strong> Нажмите <strong>«Сохранить изменения»</strong>, чтобы применить настройки блока и ручные закрепления вместе. Если <a href="./../global-settings">внешний агент</a> успел изменить этот же блок, откройте настройки заново и повторите правки.</li><li><strong>Новинки сезона.</strong> Включите блок на вкладке <strong>«Главная страница»</strong>, задайте заголовок и количество товаров. Нажмите <strong>«Отметить новинки»</strong> и выберите товары, которые хотите показать первыми. Отметка сразу сохраняется в карточке товара. Её также можно поставить в разделе <strong>«Основное и цены»</strong> самой карточки и сохранить карточку. Режим <strong>«Автоматически»</strong> ставит отмеченные товары в начало и заполняет свободные места последними добавленными. Если отметок хватает на весь блок, в нём будут только отмеченные товары. Режим <strong>«Только отмеченные»</strong> позволяет оставить блок без автоматического пополнения. В обоих режимах учитываются только товары, видимые покупателям.</li><li><strong>Каталог на главной.</strong> На вкладке <strong>«Главная страница»</strong> раскройте <strong>«Мини-каталог и формат карточек»</strong>. Выберите режим показа и задайте заголовок. В автоматическом и компактном режимах поле <strong>«Макс. позиций»</strong> задаёт предел от 2 до 48 позиций. Полный режим показывает все позиции, видимые покупателям. Автоматический режим скрывает каталог, если таких позиций больше 12 и на главной уже видны хиты или новинки.</li><li><strong>Подписи карточек.</strong> В том же блоке задайте стандартный префикс цены и текст кнопки. Подпись в карточке отдельной позиции имеет приоритет. Нажмите <strong>«Сохранить изменения»</strong> и проверьте результат в предпросмотре. Если внешний агент изменил настройки каталога, откройте редактор заново и повторите правку.</li><li><strong>Слово мастера.</strong> На вкладке <strong>«Главная страница»</strong> раскройте <strong>«Слово мастера / Манифест»</strong>. Включите блок, введите заголовок, подпись автора и цитату. Нажмите <strong>«Загрузить фото автора»</strong>, чтобы выбрать портрет. Кнопка <strong>«Добавить факт»</strong> добавляет показатель, например 15 лет опыта. Нажмите <strong>«Сохранить изменения»</strong> и проверьте раздел в предпросмотре. Если внешний агент изменил этот же блок после открытия формы, откройте редактор заново и повторите правки.</li><li><strong>Журнал на главной.</strong> Откройте <strong>«Журнал и статьи на главной»</strong>, включите блок, задайте заголовок и укажите от 1 до 9 публикаций в поле <strong>«Макс. позиций»</strong>. Нажмите <strong>«Сохранить изменения»</strong> и проверьте предпросмотр. Блок появляется, когда журнал сайта включён и у выбранной витрины есть опубликованные записи. Ссылка <strong>«Все публикации»</strong> ведёт к полному журналу.</li><li><strong>Отзывы и примеры работ.</strong> На вкладке <strong>«Главная страница»</strong> раскройте <strong>«Отзывы и кейсы клиентов»</strong>. Включите блок, задайте заголовок и подзаголовок. Нажмите <strong>«Добавить отзыв / кейс»</strong>, заполните <strong>«Имя клиента»</strong> и <strong>«Текст отзыва»</strong>, выберите оценку от 1 до 5. При необходимости добавьте название работы и фото. Расставьте карточки, нажмите <strong>«Сохранить изменения»</strong> и проверьте порядок в предпросмотре. Когда список пуст, блок скрывается.</li><li><strong>Частые вопросы.</strong> На вкладке <strong>«Главная страница»</strong> раскройте <strong>«Частые вопросы»</strong>, включите блок и нажмите <strong>«Добавить вопрос»</strong>. Заполните вопрос и ответ, расставьте карточки и нажмите <strong>«Сохранить изменения»</strong>. Блок появится на витрине, только если в списке есть хотя бы один вопрос с ответом.</li><li><strong>Условия заказа.</strong> Раскройте <strong>«Условия заказа и быстрая связь»</strong>. Включите блок и выберите, какие условия доставки и оплаты показать. Можно задать текст кнопки и выбрать, куда она ведёт. Чтобы вернуть привычный способ связи, выберите <strong>«Кнопка связи по умолчанию»</strong> и очистите текст кнопки.</li><li><strong>Шаблон главной.</strong> Выберите шаблон и нажмите <strong>«Применить шаблон»</strong>. Проверьте заполненные поля и при необходимости измените их. Изображения, слайды и порядок блоков сохраняются. Нажмите <strong>«Сохранить изменения»</strong>, чтобы применить шаблон и правки вместе. Если настройки главной уже изменились, откройте редактор заново и повторите правки.</li><li><strong>Закрепление хитов:</strong> нажмите <strong>«Добавить вручную»</strong>, найдите товар по названию и выберите его. Закреплённые позиции идут первыми. Их можно переставить кнопками <strong>«Выше»</strong> и <strong>«Ниже»</strong>. Ту же отметку можно поставить или снять в карточке товара через <strong>«Избранное на главной»</strong>.</li><li><strong>Проверка состава:</strong> сверяйтесь со списком <strong>«На главной»</strong>. Число в скобках показывает, сколько единиц продано за период. Строки под пометкой <strong>«Не попадут на главную»</strong> остаются доступными для закрепления. Если продаж нет, можно заполнить блок вручную. Режим <strong>«Вручную»</strong> показывает только закреплённые позиции в пределах максимума. При пустом списке блок скрывается.</li></ul></li><li><strong>Группа «2. КАТАЛОГ И КОНТЕНТ»:</strong><ul><li>В <strong>«Настройках каталога»</strong> задайте состав карточек и разделов сайта. <ol><li>На вкладке <strong>«Типы товаров»</strong> найдите карточку с меткой <strong>«Базовый прототип»</strong>. Остальные типы расположены под ней с отступом. Их сводки показывают, сколько сквозных полей включено, сколько добавлено напрямую или через группы и сколько сквозных полей отключено. <ul><li>Нажмите карандаш у прототипа и отметьте общие поля, например цвет. Рядом с кнопкой <strong>«Сохранить»</strong> программа напомнит, что изменения распространяются на все типы товаров.</li><li>Чтобы показывать класс или серию на карточках, настройте поле <strong>«Атрибут для бейджа изделия (класс, серия)»</strong> в базовом типе <strong>«Товар»</strong>. У дочерних типов по умолчанию выбран вариант <strong>«Наследовать из базового типа»</strong>. Для отдельного типа можно выбрать другую доступную характеристику или <strong>«Отключено (только промо-бейдж)»</strong>.</li><li>Заполните выбранную характеристику в карточке товара. Например, значение «Премиум» появится рядом с промо-бейджем. Если характеристика исключена из типа или оставлена пустой в карточке, бейдж класса скрывается. Чтобы увидеть изменения на сайте, обновите опубликованную витрину.</li><li>Чтобы убрать поле у одного типа, снимите галочку в его редакторе. Поле переместится в <strong>«Отключённые сквозные»</strong>. Если вернуть галочку, сохранённое значение снова будет доступно в карточке.</li><li>Правила заполнения настраиваются отдельно для каждого типа. Например, для сумки включите поля «Есть плечевой ремень?» и «Длина ремня». В правиле длины выберите условие показа при ответе «Да». Перед отключением управляющего поля измените зависимое правило.</li><li>Чтобы проверить привязки на активной витрине, нажмите название типа или кнопку <strong>«Товары»</strong> со счётчиком. В окне видны характеристики и общее число карточек, включая неопубликованные и архивные. Нажмите строку товара, чтобы открыть его карточку. Кнопка <strong>«Загрузить ещё»</strong> добавляет по 10 строк.</li></ul></li><li>В <strong>«Характеристики»</strong> задайте названия полей. Для одиночного или множественного выбора перечислите значения по одному на строку. Для числовой характеристики укажите единицу измерения. Отметьте <strong>«В фильтрах каталога»</strong>, если покупателям нужно отбирать товары по этому полю.</li><li>В разделе <strong>«Характеристики»</strong> выберите <strong>«Группы характеристик»</strong> и нажмите <strong>«Создать группу»</strong> (кнопка со знаком «плюс»). Назовите её и отметьте поля. Затем выберите группу в редакторе нужных типов. Изменения группы действуют во всех подключённых типах. Поле с несколькими источниками показывается один раз. Отключённое сквозное поле остаётся выключенным и после подключения группы.</li><li>В <strong>«Категории»</strong> настройте разделы и тип по умолчанию для новой карточки. Смена категории у сохранённого товара сохраняет его тип. В поле <strong>«Порядок фильтров по кодам»</strong> перечислите через запятую коды нужных характеристик в порядке показа. Пустое поле включает автоматический подбор фильтров по ассортименту раздела. Адрес подкатегории включает родительский раздел, например <code>/catalog/remni/neproshitye/</code>.</li><li>В разделе <strong>«Связанные товары»</strong> включите показ вариантов, выберите способ группировки и нажмите <strong>«Сохранить настройки связанных товаров»</strong>.</li></ol></li><li>Во вкладке <strong>«Товары на витрине»</strong> можно сохранить карточку с выключенной публикацией и вернуться к заполнению позже. Поле <strong>«Бейдж»</strong> снабжено кнопками быстрого выбора (ХИТ, НОВИНКА, АКЦИЯ) и поддерживает одновременный показ двух бейджей: системного класса изделия из характеристик и ручного промо-бейджа. Перед публикацией редактор укажет недостающие обязательные поля. Чтобы дополнить ранее опубликованные карточки, выберите <strong>«Незаполненные поля»</strong>. Чтобы сделать «Непрошитые» подкатегорией, откройте её редактор и в поле <strong>«Родительская категория»</strong> выберите «Ремни». Значение <strong>«Верхний уровень»</strong> оставляет категорию самостоятельным разделом. В редакторе можно добавить краткое описание и загрузить постер. Постер появится в начале страницы категории и на её карточке на главной. Кнопка <strong>«К товарам»</strong> прокручивает страницу к списку позиций.</li><li><strong>Страницы сайта:</strong> наполните разделы «Доставка и оплата», «О мастерской», «Возврат и гарантия». Сгенерируйте правовые документы по 152-ФЗ с вашими реквизитами. Выберите для каждой страницы <strong>«Отображать в главном меню»</strong> и <strong>«Отображать в меню подвала»</strong> по отдельности. Страница «Контакты» появляется при сборке, если заполнен телефон, электронная почта, город или хотя бы один видимый канал связи. Меняйте эти сведения в разделе <strong>«Бренд и контакты»</strong>. После пересборки они обновятся на странице и внизу сайта. Ссылка на Рутуб отображается серым фирменным значком с буквой R в круге. В подвале и меню его цвет меняется при наведении и при выборе ссылки с клавиатуры. Для ссылки на «Контакты» действуют те же отметки. Сборка также поддерживает адреса <code>/contact</code> и <code>/oplata-i-dostavka</code>, если их не занимает рубрика журнала.</li><li><strong>Статьи и блог:</strong> ведите авторский журнал мастерской для привлечения поискового трафика и повышения доверия аудитории.</li></ul></li><li><strong>Группа «3. ПРОДАЖИ И ДОСТАВКА»:</strong><ul><li>Настройте доступные способы передачи заказа (курьер, почта, транспортная компания, самовывоз из мастерской) и варианты оплаты.</li><li>В разделе <strong>«Чекаут и заявки»</strong> выберите прямой диалог, бота Телеграм или серверную форму. Если витрина принимала заказы через Яндекс Формы, сохраните новый канал и заново опубликуйте сайт. Ранее сохранённые заказы доступны в столе заказов.</li><li>Для серверной формы укажите <strong>«Email для уведомлений о заказах»</strong>. Если оставить поле пустым, обработчик возьмёт адрес из контактов витрины. Сохраните настройки и заново опубликуйте сайт на хостинге с поддержкой PHP.</li></ul></li><li>Нажмите кнопку <strong>«Сохранить изменения»</strong>.</li></ol><hr><h3 id="конструктор-сквозных-блоков-и-области-размещения" tabindex="-1">Конструктор сквозных блоков и области размещения <a class="header-anchor" href="#конструктор-сквозных-блоков-и-области-размещения" aria-label="Permalink to &quot;Конструктор сквозных блоков и области размещения&quot;">​</a></h3><p>Конструктор блоков позволяет один раз оформить информационный или конверсионный элемент и автоматически выводить его на нужных страницах витрины.</p><h4 id="доступные-области-размещения-раионы-страниц" tabindex="-1">Доступные области размещения (районы страниц) <a class="header-anchor" href="#доступные-области-размещения-раионы-страниц" aria-label="Permalink to &quot;Доступные области размещения (районы страниц)&quot;">​</a></h4><ul><li><strong>«В конце материала»:</strong> блок выводится сразу под карточкой товара или статьи публикации, продолжая внимание посетителя.</li><li><strong>«Перед подвалом»:</strong> сквозная зона над футером сайта, доступная для карточек товаров, публикаций журнала и обычных страниц («О нас», «Доставка и оплата»).</li></ul><h4 id="библиотека-типов-блоков-и-способов-вывода" tabindex="-1">Библиотека типов блоков и способов вывода <a class="header-anchor" href="#библиотека-типов-блоков-и-способов-вывода" aria-label="Permalink to &quot;Библиотека типов блоков и способов вывода&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">Способ вывода</th><th style="text-align:left;">Назначение и состав</th><th style="text-align:left;">Где рекомендуется размещать</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Частые вопросы</strong></td><td style="text-align:left;">Список раскрывающихся аккордеонов с ответами. Настраивается список вопросов и развернутых ответов мастера.</td><td style="text-align:left;">В карточках сложных изделий (уход, гарантия) или в конце сервисных страниц.</td></tr><tr><td style="text-align:left;"><strong>Карточки</strong></td><td style="text-align:left;">Адаптивная сетка карточек: заголовок, пояснительный текст, загруженное изображение (растровое или векторное) и описание изображения для поисковой оптимизации.</td><td style="text-align:left;">Преимущества мастерской, этапы индивидуального заказа, условия доставки и гарантийные обязательства.</td></tr><tr><td style="text-align:left;"><strong>Подборка из каталога («Смотрите также»)</strong></td><td style="text-align:left;">Автоматическая карусель сопутствующих позиций из каталога с регулируемым ограничением количества (по умолчанию до 4 позиций).</td><td style="text-align:left;">В конце карточки товара или услуги («В конце материала») для допродаж.</td></tr><tr><td style="text-align:left;"><strong>Позиция из публикации («Товар из статьи»)</strong></td><td style="text-align:left;">Компактная карточка изделия, выбранного в поле «Привязать товар из каталога» редактора статьи журнала.</td><td style="text-align:left;">В конце публикаций блога для прямой конверсии читателей в покупателей.</td></tr></tbody></table><h4 id="пошаговыи-порядок-создания-и-размещения" tabindex="-1">Пошаговый порядок создания и размещения <a class="header-anchor" href="#пошаговыи-порядок-создания-и-размещения" aria-label="Permalink to &quot;Пошаговый порядок создания и размещения&quot;">​</a></h4><ol><li><strong>Создание типа и блока:</strong> в группе <strong>«Основа и дизайн»</strong> откройте <strong>«Области и блоки → Типы блоков»</strong>. Нажмите <strong>«Добавить блок»</strong> внутри готового типа (либо создайте собственный тип через кнопку <strong>«Добавить тип блока»</strong>, указав базовый способ вывода) и задайте название в редакторе и заголовок на сайте.</li><li><strong>Наполнение контентом:</strong> для вопросов заполните формулировки и ответы; для карточек добавьте элементы с изображениями и описаниями; для каталога укажите предельное число карточек.</li><li><strong>Размещение в области:</strong> перейдите на вкладку <strong>«Области»</strong>, нажмите <strong>«Добавить блок»</strong> у нужной зоны (<strong>«В конце материала»</strong> или <strong>«Перед подвалом»</strong>) и выберите созданный блок.</li><li><strong>Таргетинг и фильтрация показа:</strong> отметьте целевые типы страниц («Карточки товаров», «Публикации», «Обычные страницы»). При необходимости укажите точечные страницы через <strong>«Добавить отдельную страницу»</strong> или задайте исключения через <strong>«Исключить отдельную страницу»</strong> (правило исключения всегда имеет приоритет).</li><li><strong>Управление порядком:</strong> расставьте блоки в области кнопками <strong>«Выше»</strong> и <strong>«Ниже»</strong>, включите показ тумблером <strong>«Показывать блок»</strong>, сохраните изменения и проверьте витрину в режиме предпросмотра.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Содержание и настройки блока обновляются во всех местах его размещения одновременно при следующей сборке витрины. Кнопка <strong>«Убрать из области»</strong> лишь отвязывает блок от конкретного района, сохраняя его в библиотеке для будущего использования.</p></div><hr><h2 id="характеристики-и-параметры-товаров" tabindex="-1">Характеристики и параметры товаров <a class="header-anchor" href="#характеристики-и-параметры-товаров" aria-label="Permalink to &quot;Характеристики и параметры товаров&quot;">​</a></h2><p>Покупатели интернет-витрины выбирают изделия по точным потребительским свойствам: цвету, размерам, материалам, совместимости и типам фурнитуры. Чтобы не заводить одинаковые поля вручную для каждого изделия, в ОмниКрафт ЕРП встроена многоуровневая таксономия: отдельные характеристики, многоразовые группы параметров и фасетные фильтры каталога.</p><h3 id="цеховая-задача-и-структура-групп-характеристик" tabindex="-1">Цеховая задача и структура групп характеристик <a class="header-anchor" href="#цеховая-задача-и-структура-групп-характеристик" aria-label="Permalink to &quot;Цеховая задача и структура групп характеристик&quot;">​</a></h3><p>В ремесленной мастерской или сервисном центре многие типы продукции делят единый набор технических параметров. Например, для ремней, сумок и кошельков одинаково важны «Вид кожи», «Толщина полотна» и «Цвет нити».</p><ol><li><strong>Единый источник истины:</strong> создав группу характеристик один раз, мастер подключает её к десяткам типов товаров.</li><li><strong>Бесконфликтное наследование:</strong> если характеристика входит одновременно в базовый тип и в подключенную группу, система исключает дубли — покупатель видит поле в карточке ровно один раз.</li><li><strong>Автоматическая фасетная фильтрация:</strong> отмеченные характеристики автоматически формируют боковые фильтры в каталоге витрины, помогая посетителю моментально отсеять неподходящие варианты.</li></ol><h3 id="предварительные-условия" tabindex="-1">Предварительные условия <a class="header-anchor" href="#предварительные-условия" aria-label="Permalink to &quot;Предварительные условия&quot;">​</a></h3><p>Перейдите в панель <strong>«Управление сайтом»</strong> ➔ блок <strong>«2. КАТАЛОГ И КОНТЕНТ»</strong> ➔ подвкладка <strong>«Настройки каталога»</strong>.</p><h3 id="пошаговыи-порядок-создания-групп-и-настроики-фильтрации" tabindex="-1">Пошаговый порядок создания групп и настройки фильтрации <a class="header-anchor" href="#пошаговыи-порядок-создания-групп-и-настроики-фильтрации" aria-label="Permalink to &quot;Пошаговый порядок создания групп и настройки фильтрации&quot;">​</a></h3><ol><li><strong>Создание отдельных характеристик:</strong><ul><li>Откройте <strong>«Характеристики»</strong> → <strong>«Все характеристики»</strong>. Поиск находит поля по названию и коду;</li><li>Нажмите кнопку <strong>«Добавить характеристику»</strong>;</li><li>Укажите системное имя, название для витрины и тип поля (текстовая строка, число с единицей измерения или список значений);</li><li>Для свойств, по которым требуется поиск на сайте, отметьте галочку <strong>«В фильтрах каталога»</strong>;</li><li>Нажмите кнопку <strong>«Сохранить»</strong>.</li></ul></li><li><strong>Формирование группы характеристик:</strong><ul><li>В <strong>«Характеристики»</strong> выберите <strong>«Группы характеристик»</strong>;</li><li>Нажмите <strong>«Создать группу»</strong> (кнопка со знаком «плюс»);</li><li>В открывшемся модальном окне введите название набора в поле <strong>«Название группы»</strong> (например, <em>«Параметры кожи и фурнитуры»</em>, <em>«Габариты и масса изделия»</em>);</li><li>Отметьте чекбоксами нужные атрибуты из сформированного перечня характеристик;</li><li>Нажмите кнопку <strong>«Сохранить»</strong>. Группа появится в реестре с перечислением включенных полей.</li></ul></li><li><strong>Привязка группы к типу продукции:</strong><ul><li>Откройте подвкладку <strong>«Типы товаров»</strong>;</li><li>Нажмите иконку карандаша рядом с требуемым типом изделия (например, <em>«Ремни ручной работы»</em>);</li><li>В секции групп выберите созданный набор характеристик и нажмите кнопку <strong>«Сохранить»</strong>;</li><li>Все поля группы станут доступны для заполнения во всех карточках изделий этого типа.</li></ul></li><li><strong>Управление порядком фильтров в каталоге:</strong><ul><li>Перейдите на подвкладку <strong>«Категории»</strong>;</li><li>В редакторе нужной категории найдите поле <strong>«Порядок фильтров по кодам»</strong>;</li><li>Укажите через запятую коды характеристик в желаемой очередности показа на сайте (например, <code>color, leather_type, buckle_width</code>);</li><li>Если оставить поле пустым, витрина автоматически расставит фильтры по фактической наполненности ассортимента раздела.</li></ul></li><li><strong>Редактирование и удаление групп:</strong><ul><li>Для изменения состава полей нажмите кнопку <strong>«Редактировать группу»</strong> в строке набора. Правки применятся ко всем подключенным типам товаров;</li><li>Для удаления группы нажмите кнопку <strong>«Удалить»</strong>. Если группа привязана к товарам с заполненными значениями, защитный контур предотвратит случайную потерю данных и уведомит о зависимостях.</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">Подсказка по сквозным полям</p><p>Общие характеристики, например страну производства, добавляйте в базовый тип. Характеристики, которые нужны только одному типу, например длину ремня, добавляйте в его редакторе.</p></div><hr><h3 id="шаг-2-подготовка-карточек-к-показу" tabindex="-1">Шаг 2. Подготовка карточек к показу <a class="header-anchor" href="#шаг-2-подготовка-карточек-к-показу" aria-label="Permalink to &quot;Шаг 2. Подготовка карточек к показу&quot;">​</a></h3><ol><li>Перейдите во вкладку <strong>«Товары на витрине»</strong>. Пока загружается список карточек, вверху раздела видна полоса загрузки.</li><li>В верхнем правом углу выберите режим отображения: наглядная сетка карточек 3:4 или компактный реестр для быстрой ревизии ассортимента.</li><li>Нажмите на нужную карточку для перехода в редактор: <ul><li><strong>1. Основное и цены:</strong> задайте цену, префикс «от », отметку, адрес страницы, категорию и модель.</li><li><strong>2. Медиа (фото):</strong> добавьте снимки, расставьте очередность и назначьте заглавную фотографию («★ Обложка»).</li><li><strong>3. Характеристики и доставка:</strong> заполните параметры изделия для фильтров каталога, укажите транспортировочную тару, габариты посылки и вес брутто для расчета доставки.</li><li><strong>4. Опции заказа:</strong> настройте интерактивные модификаторы для покупателя (размер изделия, гравировка, подарочная коробка).</li><li><strong>5. Лендинг и секции:</strong> оформите подробное описание в Markdown и подключите модульные промо-блоки (преимущества, слово мастера, видео, частые вопросы).</li></ul></li><li>Нажмите <strong>«Сохранить»</strong>. Когда карточка готова к показу, включите <strong>«Опубликовать на сайте»</strong> в списке товаров или в самой карточке.</li></ol><p>Если карточку ещё не сохраняли, переключатель в списке откроет её для заполнения. В каждой витрине карточку нужно сохранить отдельно.</p><h4 id="как-управлять-наличием-и-заказами" tabindex="-1">Как управлять наличием и заказами <a class="header-anchor" href="#как-управлять-наличием-и-заказами" aria-label="Permalink to &quot;Как управлять наличием и заказами&quot;">​</a></h4><p>Откройте <strong>«Управление сайтом»</strong> → <strong>«Категории и товары»</strong> → <strong>«Типы товаров»</strong>. В базовом типе <strong>«Товар»</strong> задайте общие правила в блоке <strong>«Наличие и отображение на витрине»</strong>. Свободный остаток рассчитывается за вычетом резерва.</p><ol><li>В блоке <strong>«Если товар в наличии»</strong> настройте показ метки и её текст. Отдельный флажок показывает покупателю точное число свободных единиц в карточке.</li><li>В блоке <strong>«Если товара нет в наличии»</strong> выберите один из трёх сценариев.</li></ol><table tabindex="0"><thead><tr><th>Сценарий</th><th>Что видит покупатель при нулевом свободном остатке</th></tr></thead><tbody><tr><td><strong>«Показывать в каталоге и принимать заказы»</strong></td><td>Кнопку покупки. При желании добавьте метку «Под заказ» и заметку о сроке изготовления.</td></tr><tr><td><strong>«Показывать как образец»</strong></td><td>Карточку в каталоге и поиске, метку и заметку по вашим настройкам. При наличии контактов кнопка <strong>«Обсудить заказ»</strong> открывает способы связи. В сообщении для мессенджера уже указаны название и цена образца.</td></tr><tr><td><strong>«Скрыть из каталога»</strong></td><td>Карточка исчезает с витрины, из поиска и карты сайта.</td></tr></tbody></table><p>Для товаров и услуг без складского учёта выберите <strong>«Показывать в каталоге и принимать заказы»</strong> и задайте подходящий текст метки.</p><h4 id="как-задать-отдельные-правила-для-типа-или-товара" tabindex="-1">Как задать отдельные правила для типа или товара <a class="header-anchor" href="#как-задать-отдельные-правила-для-типа-или-товара" aria-label="Permalink to &quot;Как задать отдельные правила для типа или товара&quot;">​</a></h4><ol><li>В дочернем типе снимите флажок <strong>«Использовать настройки базового типа»</strong>, если всей группе нужны свои правила.</li><li>Для отдельного товара откройте <strong>«Основное и цены»</strong> и снимите флажок <strong>«Использовать настройки типа»</strong>. Измените нужные параметры. Чтобы вернуть общие настройки, снова включите флажок и сохраните карточку.</li><li>Обновите опубликованную витрину. При оформлении она проверит сохранённую корзину и предложит убрать недоступные позиции или уменьшить количество.</li></ol><h4 id="как-задать-адреса-товаров-одного-типа" tabindex="-1">Как задать адреса товаров одного типа <a class="header-anchor" href="#как-задать-адреса-товаров-одного-типа" aria-label="Permalink to &quot;Как задать адреса товаров одного типа&quot;">​</a></h4><ol><li>Откройте <strong>«Управление сайтом»</strong> → <strong>«Категории и товары»</strong> → <strong>«Типы товаров»</strong> и откройте нужный тип для редактирования.</li><li>В базовом типе <strong>«Товар»</strong> настройте общий шаблон. По умолчанию в адрес входит название товара. В дочернем типе оставьте отметку <strong>«Использовать сквозной шаблон базового типа»</strong> или снимите её, чтобы собрать собственный шаблон. Предпросмотр учитывает домен текущей витрины и название редактируемого типа.</li><li>В новой карточке поле <strong>«Адрес страницы товара»</strong> заполняется по действующему шаблону. Пустые значения и отключённые для типа характеристики пропускаются. Если все части пусты, адрес формируется из названия товара. Адрес можно ввести вручную.</li></ol><p>При сохранении шаблона выберите <strong>«Только для новых карточек»</strong> или <strong>«Перегенерировать адреса товаров…»</strong>, если на текущей витрине есть подходящие карточки. Для базового типа программа учитывает его карточки и карточки дочерних типов со сквозным шаблоном. Для одной карточки можно нажать кнопку генерации рядом с полем адреса и сохранить карточку.</p><h4 id="как-обновить-ссылки-нескольких-товаров" tabindex="-1">Как обновить ссылки нескольких товаров <a class="header-anchor" href="#как-обновить-ссылки-нескольких-товаров" aria-label="Permalink to &quot;Как обновить ссылки нескольких товаров&quot;">​</a></h4><ol><li>На вкладке <strong>«Типы товаров»</strong> нажмите <strong>«Обновление ссылок (ЧПУ)»</strong>. Выберите все типы, один тип или <strong>«Базовый тип и типы со сквозным шаблоном»</strong>.</li><li>Выберите <strong>«Только товары со стандартными ссылками (рекомендуется)»</strong>, чтобы сохранить адреса, заданные вручную в этой версии. Режим <strong>«Принудительно для всех товаров»</strong> включает и такие карточки.</li><li>Нажмите <strong>«Показать изменения»</strong>. Сравните старые и новые адреса, снимите отметки у нужных товаров и нажмите <strong>«Применить изменения»</strong>.</li><li>Пересоберите и опубликуйте текущую витрину, чтобы оставить переход со старых опубликованных адресов на новые. Сборка включает правила <code>_redirects</code> для площадок, которые их поддерживают, и отдельные страницы перенаправления.</li></ol><div class="warning custom-block"><p class="custom-block-title">Когда старые ссылки перестают работать</p><p>При смене адреса в истории карточки сохраняется до пяти последних перенаправлений. Перед сборкой витрина исключает записи старше 365 дней и записи удалённых или архивных товаров. В сборку попадает до 1950 самых свежих правил для опубликованных карточек. Это оставляет запас до предела Cloudflare Pages в 2000 постоянных правил для отдельных адресов.</p><p>Меняйте шаблон, когда перестраиваете адреса каталога. Частые пробы могут вытеснить ссылки, по которым покупатели ещё приходят на витрину.</p></div><div class="info custom-block"><p class="custom-block-title">Адреса, сохранённые в предыдущих версиях</p><p>При обновлении программы прежние адреса считаются стандартными. Перед первым пакетным изменением просмотрите список и снимите отметки со ссылок, которые хотите сохранить. После ручного ввода и сохранения карточки адрес считается авторским. Кнопка генерации возвращает автоматический режим.</p></div><h4 id="как-связать-карточки-однои-модели" tabindex="-1">Как связать карточки одной модели <a class="header-anchor" href="#как-связать-карточки-однои-модели" aria-label="Permalink to &quot;Как связать карточки одной модели&quot;">​</a></h4><ol><li>Выберите одну <strong>«Модель изделия (линейка)»</strong> в техкартах нужных изделий. Для складской позиции без техкарты это поле доступно в окне <strong>«Оприходовать товар»</strong>. Кнопка со значком карандаша рядом с полем открывает окно управления моделями, где можно создать новую модель, переименовать её или удалить.</li><li>В поле <strong>«Модель товара»</strong> в карточке витрины оставьте <strong>«Со склада»</strong> для наследования или выберите другую модель для этой витрины.</li><li>В разделе <strong>«Связанные товары»</strong> включите показ вариантов и выберите <strong>«По модели изделия»</strong>. У опубликованных карточек одного типа и модели появится кнопка для перехода между вариантами.</li></ol><p>После сборки сайта выбранная модель появится в характеристиках товара. Если раньше модель была записана только текстом в характеристиках, выберите её в справочнике в карточке товара и соберите сайт заново.</p><div class="info custom-block"><p class="custom-block-title">Где посмотреть модели</p><p>Откройте <strong>«Управление сайтом»</strong> → <strong>«Категории и товары»</strong> → <strong>«Модели изделий»</strong>. В списке указано, сколько техкарт и складских позиций связано с каждой моделью.</p></div><h4 id="как-связать-товары-по-коду-или-характеристике" tabindex="-1">Как связать товары по коду или характеристике <a class="header-anchor" href="#как-связать-товары-по-коду-или-характеристике" aria-label="Permalink to &quot;Как связать товары по коду или характеристике&quot;">​</a></h4><ul><li><strong>По коду группы.</strong> Введите одинаковый <strong>«Код группы вариантов»</strong> в карточках нужных товаров. Выберите <strong>«По коду группы»</strong>. Так можно собрать одну подборку из товаров разных моделей и типов.</li><li><strong>По характеристике.</strong> Выберите поле в списке, например <strong>«По характеристике: Коллекция»</strong>, и заполните его одинаковым значением в нужных карточках.</li></ul><p>Кнопка появляется, когда в подборке есть хотя бы два опубликованных товара. Параметр <strong>«Отображать бейджи»</strong> показывает класс изделия и промоотметку. Чтобы рядом с вариантом были цвет, материал или размер, включите <strong>«Отображать характеристики»</strong> и отметьте нужные поля.</p><div class="info custom-block"><p class="custom-block-title">Если раньше группировали по модели или коду</p><p>При следующей сборке режим <strong>«По модели изделия»</strong> объединит карточки с одинаковыми моделью и типом товара. Чтобы сохранить подборки, заданные вручную, выберите <strong>«По коду группы»</strong>, сохраните настройки и соберите витрину заново.</p></div><h3 id="шаг-3-локальныи-предпросмотр-перед-публикациеи" tabindex="-1">Шаг 3. Локальный предпросмотр перед публикацией <a class="header-anchor" href="#шаг-3-локальныи-предпросмотр-перед-публикациеи" aria-label="Permalink to &quot;Шаг 3. Локальный предпросмотр перед публикацией&quot;">​</a></h3><p>Прежде чем отправлять сайт в сеть, проверьте его в реальном браузере:</p><ol><li>В верхней командной строке витрины нажмите кнопку <strong>«Живой предпросмотр»</strong> (значок глаза).</li><li>Программа мгновенно скомпилирует витрину из текущей рабочей базы данных, запустит встроенный локальный веб-сервер и откроет витрину в браузере.</li><li>Проверьте оформление заказа, адаптивность на разных разрешениях экрана и переключение тем оформления.</li><li>Откройте категорию и выберите несколько её подкатегорий. Проверьте путь <code>Магазин / Товары / Ремни: Непрошитые, Прошитые</code>. Ссылка <strong>«Ремни»</strong> снимает выбор подкатегорий, а <strong>«Товары»</strong> открывает полный каталог и сбрасывает фильтры.</li></ol><div class="info custom-block"><p class="custom-block-title">Защита от устаревшего кэша</p><p>Локальный сервер предпросмотра передает браузеру строгие заголовки запрета кэширования (<code>no-cache</code>). Любые изменения текстов или фотографий в программе отображаются сразу после обновления страницы в браузере клавишей F5.</p></div><hr><h3 id="шаг-4-публикация-и-выбор-транспорта" tabindex="-1">Шаг 4. Публикация и выбор транспорта <a class="header-anchor" href="#шаг-4-публикация-и-выбор-транспорта" aria-label="Permalink to &quot;Шаг 4. Публикация и выбор транспорта&quot;">​</a></h3><p>В панели «Управление сайтом» откройте раздел <strong>«Выгрузка сайта»</strong> и укажите подходящий метод размещения:</p><ul><li><strong>Прямая публикация на Клаудфлейр:</strong> самый быстрый современный метод без Git-репозиториев и сторонних серверов сборки. Программа сама передает только фактически измененные файлы по контрольным суммам SHA-256. Вы получаете бесплатный сертификат безопасности и глобальную скорость открытия. Для витрин в России по требованиям 152-ФЗ разрешён только прямой переход в мессенджер без формы заказа и сбора персональных данных на сайте (в настройках транспорта доступна кнопка быстрого переключения; также учитывайте возможные ограничения доступности доменов площадки в РФ).</li><li><strong>Объектное хранилище S3 (Яндекс Облако):</strong> экономичное и надежное отечественное размещение статических файлов с возможностью привязки собственного доменного имени мастерской.</li><li><strong>Свой хостинг.</strong> Укажите адрес сервера, порт, протокол передачи, имя пользователя, пароль и папку сайта на сервере. Защищённое соединение с шифрованием передаваемых файлов включено по умолчанию; поддерживаются явный режим на порту 21, скрытый режим на порту 990 и защищённый канал сервера на порту 22. При проверке подключения программа автоматически находит типовую папку сайта (<code>public_html</code>, <code>www</code>, <code>htdocs</code>, <code>httpdocs</code>), а перед публикацией при необходимости попросит указать публичный адрес сайта.</li><li><strong>Локальная папка или архив.</strong> При пустом поле пути программа выгружает каждую витрину в отдельную папку. Для отправки сайта одним файлом включите <strong>«Создавать переносимый .zip архив»</strong>. Указанному имени программа присвоит расширение <code>.zip</code>. Перед выгрузкой на компьютер программа предупредит, что сайт не попадёт в сеть, пока не настроен реальный хостинг.</li><li><strong>Страницы ГитХаб.</strong> В ранее настроенном профиле укажите репозиторий в виде <code>владелец/название</code>, ветку публикации и персональный ключ доступа. Обычная ветка — <code>gh-pages</code>.</li></ul><p>Нажмите <strong>«Проверить подключение»</strong>, чтобы увидеть пошаговую проверку соединения, прав записи, коротких адресов и работы серверного скрипта заказов (при необходимости), затем <strong>«Сохранить транспорт»</strong> и в верхней панели экрана нажмите <strong>«Опубликовать сайт»</strong>. На статических площадках (Клаудфлейр, Яндекс Облако, Страницы ГитХаб) серверное оформление заказов через <code>order.php</code> не поддерживается — используйте прямой диалог в мессенджере или свой хостинг. При переключении с <code>order.php</code> на другой канал повторная публикация автоматически удалит прежний серверный скрипт со сборки и площадки; если токен бота ранее уже попадал в статическую публикацию или историю Гит, перевыпустите его командой <code>/revoke</code> у <code>@BotFather</code> и обновите в настройках витрины. После публикации нажмите <strong>«Открыть сайт»</strong>.</p><p>При публикации на Клаудфлейр и на свой хостинг каталог открывается по <code>/catalog/</code>, а карточка товара — по адресу вида <code>/catalog/tovar</code>. На своём хостинге программа проверяет короткие адреса перед выгрузкой, закрывает доступ к скрытым служебным файлам, переносит перенаправления адресов и при необходимости добавляет правила Апач. Если хостинг не поддерживает эти правила, результат проверки содержит текст для его службы поддержки.</p><p>При переносе укажите <strong>«Временный адрес для проверки»</strong>, который выдал новый хостинг, если ваш домен ещё ведёт на прежнюю площадку. Опубликуйте витрину и только после успешной проверки переключите домен. Если вы впервые подключаете свой домен, привяжите его на стороне площадки или укажите её временный адрес.</p><p>Для просмотра с диска откройте <code>index.html</code> из экспортированной папки. Если экспортировали архив, кнопка <strong>«Открыть сайт»</strong> покажет папку с архивом. Распакуйте его целиком перед открытием <code>index.html</code>. Для проверки оформления заказа используйте предпросмотр или опубликованную витрину.</p><hr><h2 id="единыи-стол-заказов-работа-со-сделками" tabindex="-1">Единый стол заказов: Работа со сделками <a class="header-anchor" href="#единыи-стол-заказов-работа-со-сделками" aria-label="Permalink to &quot;Единый стол заказов: Работа со сделками&quot;">​</a></h2><p>Выберите витрину в верхней панели и откройте <strong>«Стол заказов»</strong>. Список, счётчики заказов и выручка относятся к выбранной витрине. Заказы, добавленные через <strong>«Новый заказ»</strong> или <strong>«Вставить из буфера»</strong>, сохраняются в ней же.</p><ol><li><p><strong>Синхронизация с ботом Телеграм:</strong> По нажатию кнопки <strong>«🔄 Синхронизация»</strong> программа связывается с официальным интерфейсом Телеграм, загружает новые входящие пакеты, расшифровывает их закрытым RSA-ключом мастера, проверяет телефон по стандарту E.164, отсекает повторные дубликаты и автоматически регистрирует заказ в базе данных CRM.</p><p>После обновления заново опубликуйте витрину, если принимаете заказы через серверную форму. Новые заявки получают номер вида <code>01.01.2026-1-1542</code>. По нему можно сверить заказ в подтверждении покупателя, письме и сообщении Телеграма. При синхронизации входящей заявки программа считывает этот номер, позиции и итоговую сумму.</p></li><li><p><strong>Заказ из переписки:</strong> Если клиент написал на Авито, ВКонтакте или в WhatsApp, скопируйте сообщение и нажмите <strong>«Вставить из буфера»</strong>. Вставьте текст в окно и нажмите <strong>«Распознать текст»</strong>. Проверьте имя, телефон, адрес доставки и позиции, затем нажмите <strong>«Создать заказ»</strong>.</p></li><li><p><strong>Шаблоны быстрых ответов:</strong> Кнопка <strong>«Ответить»</strong> открывает готовые варианты цеховых сообщений («Заказ подтвержден», «Изделие упаковано и готово к отправке», «Реквизиты для оплаты») с переходом в диалог мессенджера.</p></li><li><p><strong>Списание партий при проведении:</strong> После комплектации и отправки заказа нажмите кнопку <strong>«Провести продажу»</strong>. Программа автоматически спишет партии готовой продукции со склада по методу первых партий (ФИФО) и зафиксирует доход в журнале движения денег (ДДС).</p></li><li><p><strong>Двухфазное бронирование остатков:</strong> При фиксации заявки программа бронирует складской остаток, предотвращая случайную продажу одного и того же штучного предмета второму покупателю. Если складской остаток отсутствует, заказ помечается признаком «Под заказ». При отмене сделки изделия моментально возвращаются в статус доступных.</p></li></ol><hr><h2 id="мульти-витрины-раздельные-бренды-на-едином-складе" tabindex="-1">Мульти-витрины: Раздельные бренды на едином складе <a class="header-anchor" href="#мульти-витрины-раздельные-бренды-на-едином-складе" aria-label="Permalink to &quot;Мульти-витрины: Раздельные бренды на едином складе&quot;">​</a></h2><p>Если мастер развивает несколько независимых направлений (например, премиальные изделия ручной работы и студию сервисного обслуживания), программа позволяет вести <strong>несколько независимых витрин</strong> на базе единого пространства:</p><ul><li>В шапке витрины доступен выпадающий список выбора активной витрины;</li><li>В разделе <strong>«Мульти-витрины»</strong> создаются витрины и отображаются их адреса. Чтобы изменить адрес, выберите витрину в шапке и откройте <strong>«Бренд и контакты»</strong>.</li><li>Изделия и услуги привязываются к конкретной витрине, сохраняя сквозной учет общих материалов на складе и движения денег в единой кассе.</li></ul><hr><h2 id="разбор-внештатных-ситуации-troubleshooting" tabindex="-1">Разбор внештатных ситуаций (Troubleshooting) <a class="header-anchor" href="#разбор-внештатных-ситуации-troubleshooting" aria-label="Permalink to &quot;Разбор внештатных ситуаций (Troubleshooting)&quot;">​</a></h2><div class="faq-grid"><details class="faq-item"><summary class="faq-summary">Что делать, если витрина не открывается после сборки на GitHub Pages?</summary><div class="faq-content"><p>Проверьте статус сборки во вкладке «Публикация» и убедитесь, что в репозитории на сайте GitHub в настройках страниц выбран источник автоматической публикации. Проверьте срок действия персонального ключа доступа.</p></div></details><details class="faq-item"><summary class="faq-summary">Почему новый товар из Калькулятора не появляется в каталоге онлайн-витрины?</summary><div class="faq-content"><p>В конструкторе техкарты откройте вкладку «Витрина» и активируйте тумблер «Опубликовать на витрине». После сохранения техкарты перейдите во вкладку «Публикация» и выполните повторную сборку сайта мастера.</p></div></details><details class="faq-item"><summary class="faq-summary">Что делать при ошибке синхронизации заказов из бота Телеграм?</summary><div class="faq-content"><p>Проверьте корректность токена бота в настройках интеграции и убедитесь, что закрытый RSA-ключ на компьютере соответствует открытому ключу бота. При расхождении ключей перегенерируйте пару ключей в настройках витрины.</p></div></details></div>',98))])}const y=s(d,[["render",h]]);export{q as __pageData,y as default};
